import { AbstractEvent } from './abstract-event';

export class Event0 extends AbstractEvent {
    public addListener(listener: () => void, context?: any): void {
        this.addListenerNode(listener, context, false);
    }

    public addListenerOnce(listener: () => void, context?: any): void {
        this.addListenerNode(listener, context, true);
    }

    public removeListener(listener: () => void): void {
        super.removeListener(listener);
    }

    public dispatch(): void {
        this.state.dispatchEvent();
    }
}
